23	
24	// TODO: Investigate other cache patterns for row-major order that may be more
25	// parallelizable.
26	// https://tavianator.com/a-quick-trick-for-faster-naive-matrix-multiplication/
27	pub fn seq_matmul(a: &[f32], b: &[f32], dest: &mut [f32]) {
28	    // Zero dest, as it may be uninitialized.
29	    for d in dest.iter_mut() {
30	        *d = 0.0;
31	    }
32	    // Multiply in row-major order.
33	    // D[i,j] = sum for all k A[i,k] * B[k,j]
34	    let bits = dest.len().trailing_zeros() / 2;
35	    let n = 1 << bits;
36	    for i in 0..n {
37	        for j in 0..n {
38	            let mut sum = 0.0;
39	            for k in 0..n {
40	                sum += unsafe { a.get_unchecked(i << bits | k) * b.get_unchecked(k << bits | j) };
41	            }
42	            dest[i << bits | j] = sum;
43	        }
44	    }
45	}
46	
47	// Iterator that counts in interleaved bits.
48	// e.g. 0b0, 0b1, 0b100, 0b101, 0b10000, 0b10001, ...
49	struct SplayedBitsCounter {
50	    value: usize,
51	    max: usize,
52	}
53	
54	impl SplayedBitsCounter {
55	    fn new(max: usize) -> Self {
56	        SplayedBitsCounter { value: 0, max }
57	    }
58	}
59	
60	impl Iterator for SplayedBitsCounter {
61	    type Item = usize;
62	
63	    fn next(&mut self) -> Option<usize> {
64	        // Return only odd bits.
65	        let prev = self.value & 0x5555_5555;
66	        if prev < self.max {
67	            // Set all even bits.
68	            self.value |= 0xaaaa_aaaa;
69	            // Add one, carrying through even bits.
70	            self.value += 1;
71	            Some(prev)
72	        } else {
73	            None
74	        }
75	    }
76	}
77	
78	#[test]
79	fn test_splayed_counter() {
80	    let bits: Vec<usize> = SplayedBitsCounter::new(64).collect();
81	    assert_eq!(
82	        vec![0b0, 0b1, 0b100, 0b101, 0b10000, 0b10001, 0b10100, 0b10101],
83	        bits
84	    );
85	}
86	
87	// Multiply the matrices laid out in z order.
88	// https://en.wikipedia.org/wiki/Z-order_curve
89	#[inline(never)]
90	pub fn seq_matmulz(a: &[f32], b: &[f32], dest: &mut [f32]) {
91	    // All inputs need to be the same length.
92	    assert!(a.len() == b.len() && a.len() == dest.len());
93	    // Input matrices must be square with each side a power of 2.
94	    assert!(a.len().count_ones() == 1 && a.len().trailing_zeros() % 2 == 0);
95	    // Zero dest, as it may be uninitialized.
96	    for d in dest.iter_mut() {
97	        *d = 0.0;
98	    }
99	
100	    // Multiply in morton order
101	    // D[i,j] = sum for all k A[i,k] * B[k,j]
102	    let n = dest.len();
103	    for (ij, d) in dest.iter_mut().enumerate() {
104	        let i = ij & 0xaaaa_aaaa;
105	        let j = ij & 0x5555_5555;
