52	    pub fn new<R: RngExt>(num_bodies: usize, rng: &mut R) -> NBodyBenchmark {
53	        let bodies0: Vec<_> = (0..num_bodies)
54	            .map(|_| {
55	                let r = rng.random_range(0.0..10_000.0);
56	                let theta = rng.random_range(0.0..PI);
57	                let phi = rng.random_range(0.0..2.0 * PI);
58	                let position = Point3 {
59	                    x: r * theta.sin() * phi.cos(),
60	                    y: r * theta.sin() * phi.sin(),
61	                    z: r * theta.cos(),
62	                };
63	
64	                let velocity = Vector3 {
65	                    x: rng.random_range(-0.5..0.5) * INITIAL_VELOCITY,
66	                    y: rng.random_range(-0.5..0.5) * INITIAL_VELOCITY,
67	                    z: rng.random::<f64>() * INITIAL_VELOCITY + 10.0,
68	                };
69	
70	                let velocity2 = Vector3 {
71	                    x: rng.random_range(-0.5..0.5) * INITIAL_VELOCITY,
72	                    y: rng.random_range(-0.5..0.5) * INITIAL_VELOCITY,
73	                    z: rng.random::<f64>() * INITIAL_VELOCITY,
74	                };
75	
76	                Body {
77	                    position,
78	                    velocity,
79	                    velocity2,
80	                }
81	            })
82	            .collect();
83	
84	        let bodies1 = bodies0.clone();
85	
86	        NBodyBenchmark {
87	            time: 0,
88	            bodies: (bodies0, bodies1),
89	        }
90	    }
91	
92	    pub fn tick_par(&mut self) -> &[Body] {
93	        let (in_bodies, out_bodies) = if (self.time & 1) == 0 {
94	            (&self.bodies.0, &mut self.bodies.1)
95	        } else {
96	            (&self.bodies.1, &mut self.bodies.0)
97	        };
98	
99	        let time = self.time;
100	        out_bodies
101	            .par_iter_mut()
102	            .zip(&in_bodies[..])
103	            .for_each(|(out, prev)| {
104	                let (vel, vel2) = next_velocity(time, prev, in_bodies);
105	                out.velocity = vel;
106	                out.velocity2 = vel2;
107	
108	                let next_velocity = vel - vel2;
109	                out.position = prev.position + next_velocity;
110	            });
111	
112	        self.time += 1;
113	
114	        out_bodies
115	    }
