191	
192	/// Compute next velocity of `prev`
193	fn next_velocity(time: usize, prev: &Body, bodies: &[Body]) -> (Vector3<f64>, Vector3<f64>) {
194	    let time = time as f64;
195	    let center = Point3 {
196	        x: (time / 22.0).cos() * -4200.0,
197	        y: (time / 14.0).sin() * 9200.0,
198	        z: (time / 27.0).sin() * 6000.0,
199	    };
200	
201	    // pull to center
202	    let max_distance = 3400.0;
203	    let pull_strength = 0.042;
204	
205	    // zones
206	    let zone = 400.0;
207	    let repel = 100.0;
208	    let align = 300.0;
209	    let attract = 100.0;
210	
211	    let (speed_limit, attract_power);
212	    if time < 500.0 {
213	        speed_limit = 2000.0;
214	        attract_power = 100.9;
215	    } else {
216	        speed_limit = 0.2;
217	        attract_power = 20.9;
218	    }
219	
220	    let zone_sqrd = 3.0 * (zone * zone);
221	
222	    let mut acc = Vector3::zero();
223	    let mut acc2 = Vector3::zero();
224	
225	    let dir_to_center = center - prev.position;
226	    let dist_to_center = dir_to_center.magnitude();
227	
228	    // orient to center
229	    if dist_to_center > max_distance {
230	        let velc = if time < 200.0 {
231	            0.2
232	        } else {
233	            (dist_to_center - max_distance) * pull_strength
234	        };
235	
236	        let diff = (dir_to_center / dist_to_center) * velc;
237	        acc += diff;
238	    }
239	
240	    // TODO -- parallelize this loop too? would be easy enough, it's just a reduction
241	    // Just have to factor things so that `tick_seq` doesn't do it in parallel.
242	    let zero: Vector3<f64> = Vector3::zero();
243	    let (diff, diff2) = bodies
244	        .iter()
245	        .fold((zero, zero), |(mut diff, mut diff2), body| {
246	            let r = body.position - prev.position;
247	
248	            // make sure we are not testing the particle against its own position
249	            let are_same = r == Vector3::zero();
250	
251	            let dist_sqrd = r.magnitude2();
252	
253	            if dist_sqrd < zone_sqrd && !are_same {
254	                let length = dist_sqrd.sqrt();
255	                let percent = dist_sqrd / zone_sqrd;
256	
257	                if dist_sqrd < repel {
258	                    let f = (repel / percent - 1.0) * 0.025;
259	                    let normal = (r / length) * f;
260	                    diff += normal;
261	                    diff2 += normal;
262	                } else if dist_sqrd < align {
263	                    let thresh_delta = align - repel;
264	                    let adjusted_percent = (percent - repel) / thresh_delta;
265	                    let q = (0.5 - (adjusted_percent * PI * 2.0).cos() * 0.5 + 0.5) * 100.9;
266	
267	                    // normalize vel2 and multiply by factor
268	                    let vel2_length = body.velocity2.magnitude();
269	                    let vel2 = (body.velocity2 / vel2_length) * q;
270	
271	                    // normalize own velocity
272	                    let vel_length = prev.velocity.magnitude();
273	                    let vel = (prev.velocity / vel_length) * q;
274	
275	                    diff += vel2;
276	                    diff2 += vel;
277	                }
278	
279	                if dist_sqrd > attract {
280	                    // attract
281	                    let thresh_delta2 = 1.0 - attract;
282	                    let adjusted_percent2 = (percent - attract) / thresh_delta2;
283	                    let c =
284	                        (1.0 - ((adjusted_percent2 * PI * 2.0).cos() * 0.5 + 0.5)) * attract_power;
285	
286	                    // normalize the distance vector
287	                    let d = (r / length) * c;
288	
289	                    diff += d;
290	                    diff2 -= d;
291	                }
292	            }
293	
294	            (diff, diff2)
295	        });
296	
297	    acc += diff;
298	    acc2 += diff2;
299	
300	    // Speed limits
301	    if time > 500.0 {
302	        let acc_squared = acc.magnitude2();
303	        if acc_squared > speed_limit {
304	            acc *= 0.015;
305	        }
306	
307	        let acc_squared2 = acc2.magnitude2();
308	        if acc_squared2 > speed_limit {
309	            acc2 *= 0.015;
310	        }
311	    }
312	
313	    let mut new = prev.velocity + acc;
314	    let mut new2 = prev.velocity2 + acc2;
315	
316	    if time < 500.0 {
317	        let acs = new2.magnitude2();
318	        if acs > speed_limit {
319	            new2 *= 0.15;
320	        }
321	
322	        let acs2 = new.magnitude2();
323	        if acs2 > speed_limit {
324	            new *= 0.15;
325	        }
326	    }
327	
328	    (new, new2)
329	}
330	
